from collections import deque

def is_valid(grid, i, j):
    return 0 <= i < len(grid) and 0 <= j < len(grid[0]) and grid[i][j] == '.'

def in_bounds(pair, rows, cols):
    return 0 <= pair[0] < rows and 0 <= pair[1] < cols

def find_path(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        (cell, path) = queue.popleft()

        if cell == goal:
            return path

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_cell = (cell[0] + dx, cell[1] + dy)

            if in_bounds(new_cell, rows, cols) and is_valid(grid, new_cell[0], new_cell[1]) and new_cell not in visited:
                queue.append((new_cell, path + [new_cell]))
                visited.add(new_cell)

    return []

import random

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def is_valid_move(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    moves = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    frontier = [[start]]
    visited = set((start,))

    while frontier:
        path = random.choice(frontier)
        x, y = path[-1]
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny) and (nx, ny) not in visited:
                new_path = path + [(nx, ny)]
                if (nx, ny) == goal:
                    return new_path
                frontier.append(new_path)
                visited.add((nx, ny))
        frontier.remove(path)

    return []

def valid_moves(grid, row, col):
    if row - 1 >= 0 and grid[row - 1][col] == '.':
        yield (row - 1, col)
    if row + 1 < len(grid) and grid[row + 1][col] == '.':
        yield (row + 1, col)
    if col - 1 >= 0 and grid[row][col - 1] == '.':
        yield (row, col - 1)
    if col + 1 < len(grid[0]) and grid[row][col + 1] == '.':
        yield (row, col + 1)

def dfs(grid, start, goal, visited):
    if start == goal:
        return [start]
    if visited[start]:
        return []
    visited[start] = True
    moves = list(valid_moves(grid, *start))
    for move in moves:
        path = dfs(grid, move, goal, visited)
        if path:
            return [start] + path
    return []

