    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def backtrack(path=None, r=None, c=None):
        path = path or []
        if path[-1] == goal:
            return [path]
        if path or path[-1] != start:
            path.append((r, c))
