import heapq

def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbours(row, col):
        return [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]

    queue = [(0, start)]
    visited = set()
    path = {}

    while queue:
        distance, (row, col) = heapq.heappop(queue)

        if (row, col) == goal:
            result = [goal]
            while (row, col) != start:
                result.insert(0, path[(row, col)])
                (row, col) = path[(row, col)]
            return result

        if (row, col) not in visited:
            visited.add((row, col))
            for r, c in get_neighbours(row, col):
                if is_valid(r, c) and (r, c) not in visited:
                    heapq.heappush(queue, (distance + 1, (r, c)))
                    path[(r, c)] = (row, col)

    return []

