def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    moving_right = lambda x: (x[0], x[1] + 1)
    moving_left = lambda x: (x[0], x[1] - 1)
    moving_up = lambda x: (x[0] - 1, x[1])
    moving_down = lambda x: (x[0] + 1, x[1])

    moves = [moving_right, moving_left, moving_down, moving_up]

    def neighbors(cell):
        return [move(cell) for move in moves if 0 <= move(cell)[0] < len(grid) and 0 <= move(cell)[1] < len(grid[0]) and grid[move(cell)[0]][move(cell)[1]] == '.']

    def bidirectional_bfs(start, goal):
        q1 = [(start, [start])]
        q2 = [(goal, [goal])]
        visited_1 = set([start])
        visited_2 = set([goal])
        while q1 and q2:
            node_1, path_1 = q1.pop(0)
            node_2, path_2 = q2.pop(0)
            if node_1 == node_2:
                return path_1[::-1] + path_2[::-1]
            for neighbor_1 in neighbors(node_1):
                if neighbor_1 not in visited_1:
                    visited_1.add(neighbor_1)
                    q1.append((neighbor_1, path_1 + [neighbor_1]))
            for neighbor_2 in neighbors(node_2):
                if neighbor_2 not in visited_2:
                    visited_2.add(neighbor_2)
                    q2.append((neighbor_2, path_2 + [neighbor_2]))
        return []

    return bidirectional_bfs(start, goal)

