        return path[::-1]

    for direction in directions:
        next_cell = (current[0] + direction[0], current[1] + direction[1])

        if is_valid(grid, next_cell[0], next_cell[1]) and next_cell not in visited:
            visited.add(next_cell)
            stack.push(current)
            result = dfs_helper(grid, next_cell, visited, stack)
            if result:
                return result
            stack.pop()
            visited.remove(next_cell)

    return None

